    public function run(): void
    {
        foreach ($this->posts() as $i => $data) {
            Post::updateOrCreate(
                ['slug' => Str::slug($data['title'])],
                [
                    ...$data,
                    'published_at' => now()->subDays(($i + 1) * 6),
                    'is_active' => true,
                ]
            );
        }
    }

